create extension if not exists pgcrypto;
create table public.admin_users (user_id uuid primary key references auth.users(id) on delete cascade);
create table public.books (id uuid primary key default gen_random_uuid(), slug text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'), title text not null check (length(trim(title)) > 0), author text not null check (length(trim(author)) > 0), description text not null default '', cover_path text, status text not null default 'planned' check (status in ('planned','reading','read')), final_rating numeric(3,1) check (final_rating between 0 and 5), published boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.meetings (id uuid primary key default gen_random_uuid(), book_id uuid not null references public.books(id) on delete cascade, starts_at timestamptz, place text, notes text not null default '', published boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.reviews (id uuid primary key default gen_random_uuid(), book_id uuid not null references public.books(id) on delete cascade, author_name text not null check(length(trim(author_name)) > 0), body text not null check(length(trim(body)) > 0), rating numeric(3,1) check (rating between 0 and 5), published boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.meeting_photos (id uuid primary key default gen_random_uuid(), meeting_id uuid not null references public.meetings(id) on delete cascade, storage_path text not null unique, caption text not null default '', sort_order integer not null default 0);
create table public.club_settings (id integer primary key default 1 check(id = 1), name text not null, description text not null default '', links jsonb not null default '[]'::jsonb check(jsonb_typeof(links) = 'array'));
create index meetings_starts_at_idx on public.meetings(starts_at); create index meetings_book_idx on public.meetings(book_id); create index reviews_book_idx on public.reviews(book_id); create index photos_meeting_idx on public.meeting_photos(meeting_id);
create function public.is_admin() returns boolean language sql stable security definer set search_path = '' as $$ select exists (select 1 from public.admin_users where user_id = (select auth.uid())) $$;
revoke all on function public.is_admin() from public; grant execute on function public.is_admin() to anon, authenticated;
create function public.touch_updated_at() returns trigger language plpgsql set search_path = '' as $$ begin new.updated_at = now(); return new; end $$;
create trigger books_touch before update on public.books for each row execute function public.touch_updated_at();
create trigger meetings_touch before update on public.meetings for each row execute function public.touch_updated_at();
create trigger reviews_touch before update on public.reviews for each row execute function public.touch_updated_at();
alter table public.admin_users enable row level security; alter table public.books enable row level security; alter table public.meetings enable row level security; alter table public.reviews enable row level security; alter table public.meeting_photos enable row level security; alter table public.club_settings enable row level security;
create policy admin_read_self on public.admin_users for select to authenticated using (user_id = (select auth.uid()));
create policy books_read on public.books for select to anon, authenticated using (published or public.is_admin());
create policy meetings_read on public.meetings for select to anon, authenticated using ((published and exists(select 1 from public.books b where b.id=book_id and b.published)) or public.is_admin());
create policy reviews_read on public.reviews for select to anon, authenticated using ((published and exists(select 1 from public.books b where b.id=book_id and b.published)) or public.is_admin());
create policy photos_read on public.meeting_photos for select to anon, authenticated using (exists(select 1 from public.meetings m join public.books b on b.id=m.book_id where m.id=meeting_id and m.published and b.published) or public.is_admin());
create policy settings_read on public.club_settings for select to anon, authenticated using (true);
create policy books_admin on public.books for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy meetings_admin on public.meetings for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy reviews_admin on public.reviews for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy photos_admin on public.meeting_photos for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy settings_admin on public.club_settings for all to authenticated using (public.is_admin()) with check (public.is_admin());
insert into storage.buckets (id,name,public,file_size_limit,allowed_mime_types) values ('club-media','club-media',false,10485760,array['image/jpeg','image/png','image/webp']);
create policy media_read on storage.objects for select to anon, authenticated using (bucket_id='club-media' and (public.is_admin() or exists(select 1 from public.books b where b.cover_path=name and b.published) or exists(select 1 from public.meeting_photos p join public.meetings m on m.id=p.meeting_id join public.books b on b.id=m.book_id where p.storage_path=name and m.published and b.published)));
create policy media_insert on storage.objects for insert to authenticated with check (bucket_id='club-media' and public.is_admin());
create policy media_update on storage.objects for update to authenticated using (bucket_id='club-media' and public.is_admin()) with check (bucket_id='club-media' and public.is_admin());
create policy media_delete on storage.objects for delete to authenticated using (bucket_id='club-media' and public.is_admin());
